const fc = require('fast-check');
const authService = require('../utils/authService');

/**
 * Property 11: Authentication API Key Validation
 * For any API key, validating it should return true for valid keys and false for invalid keys.
 * Validates: Requirements 4.1, 9.1
 */

/**
 * Property 11a: Any API key generated by generateAPIKey() is always valid when passed to validateAPIKey()
 * Validates: Requirements 4.1, 9.1
 */
describe('Property 11: Authentication API Key Validation', () => {
    beforeEach(() => {
        authService.clearAll();
    });

    test('Property 11a: generated API keys are always valid after being stored', () => {
        /**
         * **Validates: Requirements 4.1, 9.1**
         *
         * For any API key produced by generateAPIKey(), storing it and then
         * validating it must always return isValid === true.
         */
        fc.assert(
            fc.property(
                fc.nat({ max: 99 }), // generate up to 100 keys (index used for userId)
                (index) => {
                    authService.clearAll();
                    const key = authService.generateAPIKey();
                    authService.storeAPIKey(key, `user-${index}`, { type: 'generated' });

                    const result = authService.validateAPIKey(key);

                    return result.isValid === true && result.userId === `user-${index}`;
                }
            ),
            { numRuns: 100 }
        );
    });

    test('Property 11b: strings not generated by generateAPIKey() fail validation', () => {
        /**
         * **Validates: Requirements 4.1, 9.1**
         *
         * For any arbitrary string that was NOT produced by generateAPIKey() and
         * NOT stored via storeAPIKey(), validateAPIKey() must return isValid === false.
         * We start from a clean state (clearAll) so no pre-loaded keys exist.
         *
         * Generated keys are always 64-character lowercase hex strings.
         * We test strings that differ in length (not 64 chars) or contain non-hex
         * characters, ensuring they are never accidentally valid.
         */
        fc.assert(
            fc.property(
                // Use strings that are NOT 64-char lowercase hex — they can never
                // collide with a key produced by generateAPIKey() (crypto.randomBytes(32).toString('hex'))
                fc.oneof(
                    fc.string({ minLength: 0, maxLength: 63 }),   // too short
                    fc.string({ minLength: 65, maxLength: 200 }),  // too long
                    // 64-char strings containing at least one non-hex character
                    fc.stringMatching(/[^0-9a-f]/).map(s => s.padEnd(64, 'x').slice(0, 64))
                ),
                (randomString) => {
                    authService.clearAll();
                    // Do NOT store randomString — it was never generated by generateAPIKey()
                    const result = authService.validateAPIKey(randomString);
                    return result.isValid === false;
                }
            ),
            { numRuns: 100 }
        );
    });

    test('Property 11c: API key validation is deterministic — same key always produces same result', () => {
        /**
         * **Validates: Requirements 4.1, 9.1**
         *
         * For any API key (stored or not), calling validateAPIKey() multiple times
         * with the same key must always return the same isValid result.
         */
        fc.assert(
            fc.property(
                fc.boolean(), // whether to store the key before validating
                (shouldStore) => {
                    authService.clearAll();
                    const key = authService.generateAPIKey();

                    if (shouldStore) {
                        authService.storeAPIKey(key, 'determinism-user');
                    }

                    const result1 = authService.validateAPIKey(key);
                    const result2 = authService.validateAPIKey(key);
                    const result3 = authService.validateAPIKey(key);

                    return (
                        result1.isValid === result2.isValid &&
                        result2.isValid === result3.isValid
                    );
                }
            ),
            { numRuns: 100 }
        );
    });
});

/**
 * Legacy property tests (kept for backward compatibility)
 */
describe('API Key Validation Property', () => {
    test('valid API keys are correctly validated', () => {
        fc.assert(fc.property(
            fc.string({ minLength: 10, maxLength: 100 }),
            (key) => {
                // Store the key first
                authService.storeAPIKey(key, 'test-user', { type: 'test' });
                
                // Validate the key
                const result = authService.validateAPIKey(key);
                
                expect(result.isValid).toBe(true);
                expect(result.userId).toBe('test-user');
                
                return true;
            }
        ), { numRuns: 100 });
    });

    test('invalid API keys are correctly rejected', () => {
        fc.assert(fc.property(
            fc.string({ minLength: 1, maxLength: 100 }).filter(key => key.length > 0),
            (key) => {
                // Start from a clean state so keys stored by previous tests
                // cannot leak in and make an unstored key appear valid.
                authService.clearAll();

                // Don't store the key - it doesn't exist
                const result = authService.validateAPIKey(key);
                
                expect(result.isValid).toBe(false);
                expect(result.reason).toBeDefined();
                
                return true;
            }
        ), { numRuns: 100 });
    });

    test('empty or null keys are rejected', () => {
        const emptyResult = authService.validateAPIKey('');
        expect(emptyResult.isValid).toBe(false);

        const nullResult = authService.validateAPIKey(null);
        expect(nullResult.isValid).toBe(false);

        const undefinedResult = authService.validateAPIKey(undefined);
        expect(undefinedResult.isValid).toBe(false);
    });

    test('generated API keys are unique and valid', () => {
        const keys = [];
        for (let i = 0; i < 10; i++) {
            const key = authService.generateAPIKey();
            keys.push(key);
            
            // Each key should be valid when stored
            authService.storeAPIKey(key, `user-${i}`);
            const result = authService.validateAPIKey(key);
            expect(result.isValid).toBe(true);
        }

        // All keys should be unique
        expect(new Set(keys).size).toBe(keys.length);
    });
});

// Unit tests for specific examples
describe('API Key Validation Unit Tests', () => {
    beforeEach(() => {
        // Clear all data before each test
        authService.clearAll();
    });

    test('generateAPIKey creates secure random keys', () => {
        const key1 = authService.generateAPIKey();
        const key2 = authService.generateAPIKey();
        
        expect(key1).not.toBe(key2);
        expect(key1).toHaveLength(64); // 32 bytes = 64 hex chars
        expect(/^[a-f0-9]+$/.test(key1)).toBe(true);
    });

    test('storeAPIKey stores key with metadata', () => {
        const key = authService.generateAPIKey();
        const metadata = { userId: 'test-user', scopes: ['read', 'write'] };
        
        const record = authService.storeAPIKey(key, 'test-user', metadata);
        
        expect(record.key).toBe(key);
        expect(record.userId).toBe('test-user');
        expect(record.metadata).toEqual(metadata);
        expect(record.createdAt).toBeDefined();
        expect(record.active).toBe(true);
    });

    test('validateAPIKey returns valid for correct key', () => {
        const key = authService.generateAPIKey();
        authService.storeAPIKey(key, 'test-user', { type: 'api' });
        
        const result = authService.validateAPIKey(key);
        
        expect(result.isValid).toBe(true);
        expect(result.userId).toBe('test-user');
        expect(result.metadata).toEqual({ type: 'api' });
    });

    test('validateAPIKey returns invalid for unknown key', () => {
        const result = authService.validateAPIKey('unknown-key-12345');
        
        expect(result.isValid).toBe(false);
        expect(result.reason).toBe('Key not found');
    });

    test('validateAPIKey returns invalid for inactive key', () => {
        const key = authService.generateAPIKey();
        authService.storeAPIKey(key, 'test-user');
        authService.deactivateAPIKey(key);
        
        const result = authService.validateAPIKey(key);
        
        expect(result.isValid).toBe(false);
        expect(result.reason).toBe('Key is inactive');
    });

    test('deactivateAPIKey deactivates key', () => {
        const key = authService.generateAPIKey();
        authService.storeAPIKey(key, 'test-user');
        
        const beforeResult = authService.validateAPIKey(key);
        expect(beforeResult.isValid).toBe(true);
        
        const deactivated = authService.deactivateAPIKey(key);
        expect(deactivated).toBe(true);
        
        const afterResult = authService.validateAPIKey(key);
        expect(afterResult.isValid).toBe(false);
    });

    test('deactivateAPIKey returns false for unknown key', () => {
        const result = authService.deactivateAPIKey('unknown-key');
        expect(result).toBe(false);
    });
});

// Session Management Tests
describe('Session Management', () => {
    beforeEach(() => {
        authService.clearAll();
    });

    test('createSession creates valid session', () => {
        const user = { id: 'user-123', roles: ['user'] };
        const session = authService.createSession(user);
        
        expect(session.sessionId).toBeDefined();
        expect(session.expiresAt).toBeDefined();
        expect(session.mfaRequired).toBe(false);
    });

    test('createSession with mfaEnabled', () => {
        const user = { id: 'user-123', roles: ['user'], mfaEnabled: true };
        const session = authService.createSession(user);
        
        expect(session.mfaRequired).toBe(true);
    });

    test('validateSession returns valid for active session', () => {
        const user = { id: 'user-123', roles: ['user'] };
        const session = authService.createSession(user);
        
        const validation = authService.validateSession(session.sessionId);
        
        expect(validation.isValid).toBe(true);
        expect(validation.session.userId).toBe('user-123');
        expect(validation.session.roles).toEqual(['user']);
    });

    test('validateSession returns invalid for unknown session', () => {
        const validation = authService.validateSession('unknown-session-123');
        
        expect(validation.isValid).toBe(false);
        expect(validation.reason).toBe('Session not found');
    });

    test('invalidateSession removes session', () => {
        const user = { id: 'user-123', roles: ['user'] };
        const session = authService.createSession(user);
        
        const beforeValidation = authService.validateSession(session.sessionId);
        expect(beforeValidation.isValid).toBe(true);
        
        const invalidated = authService.invalidateSession(session.sessionId);
        expect(invalidated).toBe(true);
        
        const afterValidation = authService.validateSession(session.sessionId);
        expect(afterValidation.isValid).toBe(false);
    });

    test('session expires after timeout', (done) => {
        // Set a short timeout for testing
        authService.setSessionTimeout(100); // 100ms
        
        const user = { id: 'user-123', roles: ['user'] };
        const session = authService.createSession(user);
        
        // Should be valid initially
        let validation = authService.validateSession(session.sessionId);
        expect(validation.isValid).toBe(true);
        
        // Wait for expiration
        setTimeout(() => {
            validation = authService.validateSession(session.sessionId);
            expect(validation.isValid).toBe(false);
            // Session may be deleted before expiration check, so check for either reason
            expect(['Session expired', 'Session not found']).toContain(validation.reason);
            done();
        }, 150);
    }, 2000);
});

// MFA Tests
describe('MFA Support', () => {
    beforeEach(() => {
        authService.clearAll();
    });

    test('initiateMFA creates valid MFA code', () => {
        const user = { id: 'user-123' };
        const result = authService.initiateMFA(user);
        
        expect(result.success).toBe(true);
        expect(result.code).toHaveLength(6);
        expect(/\d{6}/.test(result.code)).toBe(true);
        expect(result.expiresAt).toBeDefined();
    });

    test('verifyMFA validates correct code', () => {
        const user = { id: 'user-123' };
        const initiateResult = authService.initiateMFA(user);
        
        const verifyResult = authService.verifyMFA(user, initiateResult.code);
        
        expect(verifyResult.isValid).toBe(true);
        expect(verifyResult.mfaVerified).toBe(true);
    });

    test('verifyMFA rejects incorrect code', () => {
        const user = { id: 'user-123' };
        authService.initiateMFA(user);
        
        const result = authService.verifyMFA(user, '000000');
        
        expect(result.isValid).toBe(false);
        expect(result.reason).toBe('Invalid MFA code');
        expect(result.attemptsRemaining).toBe(2);
    });

    test('verifyMFA rejects after 3 failed attempts', () => {
        const user = { id: 'user-123' };
        authService.initiateMFA(user);
        
        // Try 3 wrong codes
        for (let i = 0; i < 3; i++) {
            authService.verifyMFA(user, '000000');
        }
        
        const result = authService.verifyMFA(user, '000000');
        expect(result.isValid).toBe(false);
        expect(result.reason).toBe('Too many failed attempts');
    });

    test('MFA code expires after timeout', (done) => {
        // Set a short validity for testing
        authService.setMFAValidity(100); // 100ms
        
        const user = { id: 'user-123' };
        const initiateResult = authService.initiateMFA(user);
        
        // Don't verify initially - just wait for expiration
        setTimeout(() => {
            const verifyResult = authService.verifyMFA(user, initiateResult.code);
            expect(verifyResult.isValid).toBe(false);
            // Code may be deleted before expiration check, so check for either reason
            expect(['MFA code expired', 'MFA token not found or expired', 'MFA code not found or expired']).toContain(verifyResult.reason);
            done();
        }, 150);
    }, 2000);
});

// Access Control Tests
describe('Access Control', () => {
    beforeEach(() => {
        authService.clearAll();
    });

    test('checkAccess allows admin full access', () => {
        const user = { id: 'admin-123', roles: ['admin'] };
        
        const result = authService.checkAccess(user, 'transactions', 'delete');
        
        expect(result.allowed).toBe(true);
        expect(result.role).toBe('admin');
    });

    test('checkAccess denies merchant delete access', () => {
        const user = { id: 'merchant-123', roles: ['merchant'] };
        
        const result = authService.checkAccess(user, 'transactions', 'delete');
        
        expect(result.allowed).toBe(false);
        expect(result.reason).toBe('Access denied');
    });

    test('checkAccess allows merchant read access', () => {
        const user = { id: 'merchant-123', roles: ['merchant'] };
        
        const result = authService.checkAccess(user, 'transactions', 'read');
        
        expect(result.allowed).toBe(true);
    });

    test('checkAccess denies unknown resource', () => {
        const user = { id: 'user-123', roles: ['user'] };
        
        const result = authService.checkAccess(user, 'unknown-resource', 'read');
        
        expect(result.allowed).toBe(false);
    });

    test('checkAccess denies unknown action', () => {
        const user = { id: 'user-123', roles: ['user'] };
        
        const result = authService.checkAccess(user, 'transactions', 'unknown-action');
        
        expect(result.allowed).toBe(false);
    });

    test('checkAccess checks multiple roles', () => {
        const user = { id: 'user-123', roles: ['user', 'support'] };
        
        // User role doesn't have users read, but support does
        const result = authService.checkAccess(user, 'users', 'read');
        
        expect(result.allowed).toBe(true);
    });

    test('checkAccess denies when no roles match', () => {
        const user = { id: 'user-123', roles: ['user'] };
        
        const result = authService.checkAccess(user, 'users', 'delete');
        
        expect(result.allowed).toBe(false);
    });

    test('checkAccess handles user without roles', () => {
        const user = { id: 'user-123' };
        
        const result = authService.checkAccess(user, 'transactions', 'read');
        
        expect(result.allowed).toBe(false);
        expect(result.reason).toBe('User must have roles');
    });
});

// Integration Tests
describe('Authentication Service Integration', () => {
    beforeEach(() => {
        authService.clearAll();
    });

    test('full authentication flow with MFA', () => {
        // 1. Generate and store API key
        const apiKey = authService.generateAPIKey();
        authService.storeAPIKey(apiKey, 'user-123', { type: 'api' });

        // 2. Validate API key
        const keyValidation = authService.validateAPIKey(apiKey);
        expect(keyValidation.isValid).toBe(true);
        expect(keyValidation.userId).toBe('user-123');

        // 3. Create session
        const user = { id: 'user-123', roles: ['user'] };
        const session = authService.createSession(user);
        expect(session.sessionId).toBeDefined();

        // 4. Initiate MFA
        const mfaResult = authService.initiateMFA({ id: 'user-123' });
        expect(mfaResult.success).toBe(true);

        // 5. Link session to MFA
        authService.linkMFASession('user-123', session.sessionId);

        // 6. Verify MFA
        const mfaVerify = authService.verifyMFA({ id: 'user-123' }, mfaResult.code);
        expect(mfaVerify.isValid).toBe(true);

        // 7. Validate session (should now have mfaVerified = true)
        const sessionValidation = authService.validateSession(session.sessionId);
        expect(sessionValidation.isValid).toBe(true);
        expect(sessionValidation.session.mfaVerified).toBe(true);
    });
});
